#!/usr/bin/env python3
"""make_results_a1.py -- render RESULTS_A1.md from raw_a1/SMOOTH_T1_A1.json and raw_a1/NONDET_BOUND.json (and the 1-thread raw/SMOOTH_T1.json for the agreement line).
No number is typed by hand: every cell is a field of the JSONs.  Prose is fixed text or a function of the JSON fields only.

    python make_results_a1.py <package>   ->  <package>/RESULTS_A1.md
"""
import json
import os
import sys

sys.dont_write_bytecode = True
PK = sys.argv[1].replace("\\", "/")
R = json.load(open(f"{PK}/raw_a1/SMOOTH_T1_A1.json", encoding="utf-8"))
NB = json.load(open(f"{PK}/raw_a1/NONDET_BOUND.json", encoding="utf-8"))
OLD = json.load(open(f"{PK}/raw/SMOOTH_T1.json", encoding="utf-8")) if os.path.exists(f"{PK}/raw/SMOOTH_T1.json") else None
ORDER = ["ADE6", "speed MAE", "along-track MAE", "accel MAE", "DK-VIOL", "DK-HW", "DK-TG", "heading MAE", "yaw-rate MAE", "curvature MAE", "cross-track MAE", "L1 lateral-accel MAE", "L2 curvature MAE (GT>=5.2)",
         "TAC-LAT", "TAC-LON", "S-POS@30", "S-POS@50", "S-POS@80", "M1 crawl share"]
CRAWL = ("yaw-rate MAE", "curvature MAE", "L2 curvature MAE (GT>=5.2)", "M1 crawl share")
NAME = {"CTRL": "DAG-OACC", "SOUP": "SOUP"}
NEXT = {"DOMINANT": "re-read on a fresh seed or window set before adoption; the training lever is a smooth output basis (the PI's go).",
        "MOVED": "name the rows still separated-worse against P10 per seed (listed below); the cheapest next step is S composed with the curvature-bounded decode (`stack/tanitad/refs/feasible_decode.py` envelope, KAPPA_MAX 0.2), a flag of the same tool, with its own pre-registration frozen before data.",
        "NO EFFECT": "a curvature-bounded decode (`feasible_decode.py` envelope, KAPPA_MAX 0.2) as the next zero-training arm, wired the same way as a flag of the same tool, with its own pre-registration frozen before data.",
        "HARMS": "a curvature-bounded decode (`feasible_decode.py` envelope, KAPPA_MAX 0.2) as the next zero-training arm, wired the same way as a flag of the same tool, with its own pre-registration frozen before data."}


def cell(row):
    d, lo, hi, sep = row["delta"], row["lo"], row["hi"], row["separated"]
    better = (d > 0) if row["direction"] == "higher" else (d < 0)
    flag = "B" if (sep and better) else ("W" if sep else ".")
    return f"{d:+.4f} [{lo:+.4f}, {hi:+.4f}] {flag}"


def seed_word(ps):
    if ps["A"]["DOMINANT"]:
        return "DOMINANT"
    if ps["XY"]["HARMS_seed"]:
        return "HARMS"
    if ps["XY"]["MOVED_seed"]:
        return "MOVED"
    return "NO EFFECT"


def e(x):
    return f"{x:.2e}"


ctl, tol, N = R["controls"], R["tolerances"], R["nondet_N"]
out = []
out += ["# RESULTS_A1: H-SMOOTH-T1-1 under AMENDMENT_1 (control-only, post-data, disclosed)", "",
        f"<!-- generated by code/make_results_a1.py from raw_a1/SMOOTH_T1_A1.json (sha256 of the read recorded in MANIFEST.txt) and raw_a1/NONDET_BOUND.json: no hand-typed number -->", "",
        f"Tier **T1-kin** (own executed state, logged cameras; a self-action open loop). Evidence class of every number: **MEASURED (ours; artifacts in `MANIFEST.txt`)**. Estimator on every interval: **paired episode-cluster bootstrap, B = 2,000, seed 0** "
        f"(`taniteval.ci` draw stream via the landed `gapdecomp.decompose`); it answers *would another draw of EPISODES say this?* and nothing about training variance (each arm is one training run per seed, `H-ESTIM-SEED-1`) or inference variance (the planner is deterministic). "
        f"Card `PREREG_FROZEN.md` sha256 `{R['prereg_sha256'][:8]}...` (not edited); `AMENDMENT_1.md` sha256 `{R['amendment_sha256'][:8]}...`, frozen 2026-11-02T15:41:09+0100 before any 16-thread number was read. Zero training, CPU only, 16 threads, one rollout at a time. "
        f"The outcome rule, rows, bars and estimator are the card's; the amendment changes only the controls' reference and the Y side of the decision contrast (**X - Y'**, fresh `--smooth off` rollouts of the same tool in the same session).", ""]

# ---------------------------------------------------------------- 0 headline
out += ["## 0. Headline", "", f"**Status: {R['outcome_status']}.**", ""]
out += ["| arm | seed 0 | seed 1 | outcome by the committed rule, decision contrast X - Y' (both seeds) | the same rule on X - Y banked (beside) | separated-worse rows of 19 (X - P10, s0 / s1) | separated-worse rows of 19 (X - Y', s0 / s1) |", "|---|---|---|---|---|---|---|"]
for arm in ("CTRL", "SOUP"):
    a = R["arms"][arm]
    ps = a["per_seed"]
    out.append(f"| {NAME[arm]} | {seed_word(ps['s0'])} | {seed_word(ps['s1'])} | **{a['outcome']}** | {a['outcome_on_banked_Y_beside']['outcome']} | {len(ps['s0']['A']['separated_worse_rows'])} / {len(ps['s1']['A']['separated_worse_rows'])} | "
               f"{ps['s0']['XY']['n_separated_worse_all']} / {ps['s1']['XY']['n_separated_worse_all']} |")
out += ["", "Per-seed words apply the card's precedence (DOMINANT, then HARMS, then MOVED, then NO EFFECT) to one seed; the arm word is the card's rule over both seeds. The headline arm is DAG-OACC; SOUP is stated separately. Multiplicity: HARMS tests 15 non-crawl rows x 2 seeds = 30 tests per arm, and the number of separated-worse rows is printed beside the verdict.", ""]
if OLD:
    out += [f"Agreement with the 1-thread descriptive read of `RESULTS.md` (`raw/SMOOTH_T1.json`, banked Y as reference): DAG-OACC **{OLD['arms']['CTRL']['outcome']}** (now **{R['arms']['CTRL']['outcome']}**), SOUP **{OLD['arms']['SOUP']['outcome']}** (now **{R['arms']['SOUP']['outcome']}**).", ""]

# ---------------------------------------------------------------- 1 controls
out += ["## 1. Controls and the measured nondeterminism bound", "",
        f"**Measured bound** (Y' = `{NB['Y_prime']}` against Y'' = `{NB['Y_double_prime']}`, the same configuration run twice at 16 threads; `raw_a1/NONDET_BOUND.json`): dump bit-identical **{NB['bitwise_identical_dump']}**, ticks bit-identical **{NB['bitwise_identical_ticks']}**, "
        f"{NB['n_tick_float_fields_differing']} tick float fields differ, {NB['n_ticks_with_plan_dev_gt_1e-4']} of {NB['n_ticks']} ticks have a `plan` deviation above 1e-4 m.", "",
        "| class | measured max abs deviation N | tolerance = max(1e-4, N) |", "|---|---|---|"]
for k in ("dump", "floor", "tick0", "ticks", "row"):
    out.append(f"| {k} | {e(N['N_' + k])} | {e(tol['tol_' + k])} |")
out += ["", "These bounds come from **one** replicate pair; they say how far the rig moved between two identical runs, not that no larger movement exists (AMENDMENT_1 section 3).", ""]
k1 = ctl["K1p_Yprime_vs_banked_DAGOACC_s0"]
k2 = ctl["K2p_Yprime_minus_Ybanked_rows"]
k5 = ctl["K5p_smoothed_ticks_identities"]
k1p = k1["by_arm_seed"]["CTRL_s0"]
out += ["| control | measured | tolerance | result |", "|---|---|---|---|",
        f"| **K1'** DAG-OACC s0: Y' (patched `--smooth off`, 16 threads) vs the banked dump and ticks | dump max {e(k1p['dump_max_abs_dev'])} (`fl` {e(k1p['floor_fl_max_abs_dev'])}), ticks max {e(k1p['ticks_max_abs_dev'])}, tick-0 `plan` {e(k1p['tick0_plan_max_abs_dev'])}; dump bit-identical {k1p['bit_identical_dump']}, ticks bit-identical {k1p['bit_identical_ticks']}; {k1p['n_ticks_plan_dev_gt_1e-4']} of {k1p['n_ticks']} ticks differ above 1e-4 m in `plan` | dump {e(k1['tol_dump'])}, ticks {e(k1['tol_ticks'])} | **{'PASS' if k1['PASS'] else 'FAIL at the measured tolerance'}** |",
        f"| **K2'** (Y', Y banked) on the 19 rows, DAG-OACC s0 | max abs row delta {e(k2['by_arm_seed']['CTRL_s0']['max_abs_row_delta'])} | {e(k2['tol_row'])} | **{'PASS' if k2['PASS'] else 'FAIL at the measured tolerance'}** |",
        f"| **K2''** (Y', Y'') on the 19 rows (the bound's own consistency) | max abs row delta {e(ctl['K2pp_Yprime_minus_Ydoubleprime_rows']['max_abs_row_delta'])} | {e(tol['tol_row'])} | **{'PASS' if ctl['K2pp_Yprime_minus_Ydoubleprime_rows']['PASS'] else 'FAIL'}** |",
        f"| **K3** Y - P10 reproduces the banked `SOUP_READ.json` rows within 6e-5 | {ctl['K3_Y_minus_P10_reproduces_SOUP_READ']['n_pass']} of {ctl['K3_Y_minus_P10_reproduces_SOUP_READ']['n_rows']} rows | 6e-5 | **{'PASS' if ctl['K3_Y_minus_P10_reproduces_SOUP_READ']['PASS'] else 'FAIL'}** |",
        f"| **K4** an arm against itself reads exactly 0, [0, 0] | {ctl['K4_self_minus_self_is_zero']['n_pass']} of {ctl['K4_self_minus_self_is_zero']['n_rows']} rows | exact | **{'PASS' if ctl['K4_self_minus_self_is_zero']['PASS'] else 'FAIL'}** |",
        f"| **K5'** plan clause: `plan` = `P + SG(plan_raw - P)` offline (float32 cast), S active, windows equal | max recompute deviation {e(max(v['plan_vs_P_plus_SG_max_abs_m'] for v in k5['runs'].values()))} m; S changed the plan by up to {max(v['S_changed_plan_max_abs_m'] for v in k5['runs'].values()):.3f} m | {e(k5['plan_recompute_tol_m'])} | **{'PASS' if k5['plan_clause_PASS'] else 'FAIL'}** |",
        f"| **K5'** tick-0 clause: tick-0 `plan_raw` = banked Y tick-0 `plan` (also vs Y') | vs banked max {e(max(v['tick0_plan_raw_vs_Ybanked_plan_max_abs_m'] for v in k5['runs'].values()))}; vs Y' max {e(max(v['tick0_plan_raw_vs_Yprime_plan_max_abs_m'] for v in k5['runs'].values()))} | {e(k5['tol_tick0'])} | **{'PASS' if k5['tick0_clause_PASS'] else 'FAIL at the measured tolerance'}** |",
        f"| **K5'** floor clause: X's `fl` = banked Y's `fl` (also vs Y') | vs banked max {e(max(v['floor_fl_vs_Ybanked_max_abs_dev_m'] for v in k5['runs'].values()))} m; vs Y' max {e(max(v['floor_fl_vs_Yprime_max_abs_dev_m'] for v in k5['runs'].values()))} m | {e(k5['tol_floor'])} | **{'PASS' if k5['floor_clause_PASS'] else 'FAIL at the measured tolerance'}** |",
        f"| **K6** one patched tool (sha256 `{ctl['K6_tool_identity_and_threads']['tool_copy_sha256'][:8]}...`) in all nine runs, all at 16 threads; pytest logs in `tests/` | same tool {ctl['K6_tool_identity_and_threads']['all_runs_same_tool_sha256']}, 16 threads {ctl['K6_tool_identity_and_threads']['all_threads_16']} | | **{'PASS' if ctl['K6_tool_identity_and_threads']['PASS'] else 'FAIL'}** |",
        f"| **K7** tick-0 `P` = `p10_yaw4512/p10_eval_pred6.npy` (descriptive) | max abs {e(ctl['K7_tick0_P_vs_p10_eval_pred6_descriptive']['max_abs_m']) if ctl.get('K7_tick0_P_vs_p10_eval_pred6_descriptive', {}).get('max_abs_m') is not None else 'not computed'} m | | descriptive |", ""]
out += ["Y' against the banked Y for all four arm-seeds (descriptive for the three other than DAG-OACC s0):", "", "| arm / seed | dump max dev | `fl` max dev | ticks max dev | max abs row delta (Y' - Y) | within tolerance (dump / ticks / floor / rows) |", "|---|---|---|---|---|---|"]
for kk in ("CTRL_s0", "CTRL_s1", "SOUP_s0", "SOUP_s1"):
    a_, b_ = k1["by_arm_seed"][kk], k2["by_arm_seed"][kk]
    out.append(f"| {NAME[kk.split('_')[0]]} {kk[-2:]} | {e(a_['dump_max_abs_dev'])} | {e(a_['floor_fl_max_abs_dev'])} | {e(a_['ticks_max_abs_dev'])} | {e(b_['max_abs_row_delta'])} | {a_['within_tol_dump']} / {a_['within_tol_ticks']} / {a_['within_tol_floor']} / {b_['within_tol_row']} |")
out += ["", f"Hard controls (a failure here is a defect and REFUSES the outcome): {json.dumps(R['controls_hard'])}. Banked-reference comparisons (a failure here moves the status to QUOTABLE ON Y'): {json.dumps(R['controls_soft_banked_reference'])}.", ""]

# ---------------------------------------------------------------- 2 outcome rule
out += ["## 2. The outcome rule, condition by condition (unchanged rule; HARMS and MOVED read on X - Y', D1-D3 on X - P10 with the banked P10 rows)", "",
        "| arm | seed | D1 ADE6 X - P10 | D2 no separated-worse row (X - P10) | separated-worse rows (X - P10) | D3 each family has a separated-better row | ADE6 X - Y' | all four crawl rows X - Y' separated-better | non-crawl rows X - Y' separated-worse | separated-worse rows of 19 (X - Y') | MOVED cond. | HARMS cond. | seed word |",
        "|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
for arm in ("CTRL", "SOUP"):
    for s in ("s0", "s1"):
        ps, rows = R["arms"][arm]["per_seed"][s], R["arms"][arm]["rows"][s]
        A, XY = ps["A"], ps["XY"]
        fam = ", ".join(f"{f[:3]}:{'Y' if v else 'N'}" for f, v in A["D3_by_family"].items())
        out.append(f"| {NAME[arm]} | {s} | {'PASS' if A['D1'] else 'FAIL'} ({rows['XP']['ADE6']['delta']:+.4f} m) | {'PASS' if A['D2'] else 'FAIL'} | {', '.join(A['separated_worse_rows']) or 'none'} | {'PASS' if A['D3'] else 'FAIL'} ({fam}) | "
                   f"{XY['ade6_delta']:+.4f} m | {'yes' if XY['crawl_all_separated_better'] else 'no'} | {', '.join(XY['non_crawl_separated_worse']) or 'none'} | {XY['n_separated_worse_all']} | {'met' if XY['MOVED_seed'] else 'not met'} | {'met' if XY['HARMS_seed'] else 'not met'} | {seed_word(ps)} |")
out += ["", "| arm | DOMINANT | HARMS (either seed) | MOVED (both seeds) | outcome (X - Y') | outcome on X - Y banked | moved and harms both met |", "|---|---|---|---|---|---|---|"]
for arm in ("CTRL", "SOUP"):
    a = R["arms"][arm]
    out.append(f"| {NAME[arm]} | {'yes' if a['DOMINANT'] else 'no'} | {'yes' if a['HARMS_condition'] else 'no'} | {'yes' if a['MOVED_condition'] else 'no'} | **{a['outcome']}** | {a['outcome_on_banked_Y_beside']['outcome']} | {'yes' if a['moved_and_harms'] else 'no'} |")
out.append("")

# ---------------------------------------------------------------- 3 crawl rows and ADE6
out += ["## 3. ADE6 and the four crawl rows (X - Y' decides; X - P10 uses the banked P10 rows; X - Y banked and Y' - Y beside)", "",
        "Cell = `delta [95% interval] flag`; **B** = separated on the better side of the row's direction, **W** = separated on the worse side, `.` = not separated. `share removed` = -(X - Y') / (Y' - P10) at the point estimates (ESTIMATED arithmetic, no interval).", "",
        "| arm | seed | row | X - Y' | X - P10 | X - Y banked | Y' - P10 | Y - P10 (banked) | Y' - Y (rig noise) | share removed |", "|---|---|---|---|---|---|---|---|---|---|"]
for arm in ("CTRL", "SOUP"):
    for s in ("s0", "s1"):
        rows = R["arms"][arm]["rows"][s]
        for lab in ("ADE6",) + CRAWL:
            sh = f"{-rows['XYp'][lab]['delta'] / rows['YpP'][lab]['delta']:.2f}" if lab != "ADE6" else "n/a"
            out.append(f"| {NAME[arm]} | {s} | {lab} | {cell(rows['XYp'][lab])} | {cell(rows['XP'][lab])} | {cell(rows['XY'][lab])} | {cell(rows['YpP'][lab])} | {cell(rows['YP'][lab])} | {cell(rows['YpY'][lab])} | {sh} |")
out.append("")

# ---------------------------------------------------------------- 4 all 19 rows
out += ["## 4. All 19 rows, all four families (LONGITUDINAL, LATERAL, TACTICAL, STRATEGIC) plus PRIMARY and the crawl row", ""]
for arm in ("CTRL", "SOUP"):
    for s in ("s0", "s1"):
        rows = R["arms"][arm]["rows"][s]
        out += [f"### {NAME[arm]} {s}", "", "| family | row | n (windows / episodes) | X - P10 | X - Y' | X - Y banked | Y' - Y |", "|---|---|---|---|---|---|---|"]
        for lab in ORDER:
            out.append(f"| {rows['XP'][lab]['family']} | {lab} | {rows['XP'][lab]['n']} | {cell(rows['XP'][lab])} | {cell(rows['XYp'][lab])} | {cell(rows['XY'][lab])} | {cell(rows['YpY'][lab])} |")
        out.append("")
out += ["### Rows by flag within each family (B / W / not separated)", "", "| arm | seed | family (rows) | X - P10 | X - Y' |", "|---|---|---|---|---|"]
FAMS = ("PRIMARY", "LONGITUDINAL", "LATERAL", "TACTICAL", "STRATEGIC", "crawl")
for arm in ("CTRL", "SOUP"):
    for s in ("s0", "s1"):
        rows = R["arms"][arm]["rows"][s]
        for f in FAMS:
            labs = [l for l in ORDER if rows["XP"][l]["family"] == f]

            def cnt(tab):
                b = sum(1 for l in labs if rows[tab][l]["separated"] and ((rows[tab][l]["delta"] > 0) if rows[tab][l]["direction"] == "higher" else (rows[tab][l]["delta"] < 0)))
                w = sum(1 for l in labs if rows[tab][l]["separated"]) - b
                return f"{b} / {w} / {len(labs) - b - w}"
            out.append(f"| {NAME[arm]} | {s} | {f} ({len(labs)}) | {cnt('XP')} | {cnt('XYp')} |")
out.append("")

# ---------------------------------------------------------------- 5 descriptive curvature block
out += ["## 5. Descriptive curvature block (decides nothing; v0 3-8 m/s band of the M class)", "",
        "mean |kappa| and curvature roughness (mean squared first difference of kappa) of the EXECUTED path (X, Y', banked Y, the P10 floor, the GT) and of the ISSUED plan (X before S = `plan_raw`, X after S = `plan`, Y', banked Y).", "",
        "| arm / seed | band windows | executed X | executed Y' | executed Y banked | executed P10 floor | executed GT | issued plan X before S | issued plan X after S | issued plan Y' | issued plan Y banked |", "|---|---|---|---|---|---|---|---|---|---|---|"]


def kr(d):
    return f"{d['mean_abs_kappa']:.4f} / {d['roughness_mean_sq_dkappa']:.4f}"


for arm in ("CTRL", "SOUP"):
    for s in ("s0", "s1"):
        d = R["descriptive"][f"{arm}_{s}"]
        X, Yp, Yb = d["X_smoothed"], d["Y_prime_off"], d["Y_banked"]
        out.append(f"| {NAME[arm]} {s} | {X['n_band_windows']} | {kr(X['executed_x'])} | {kr(Yp['executed_x'])} | {kr(Yb['executed_x'])} | {kr(X['executed_p10'])} | {kr(X['executed_gt'])} | "
                   f"{kr(X['issued_plan_ticks_in_band']['plan_raw'])} | {kr(X['issued_plan_ticks_in_band']['plan'])} | {kr(Yp['issued_plan_ticks_in_band']['plan'])} | {kr(Yb['issued_plan_ticks_in_band']['plan'])} |")
out.append("")

# ---------------------------------------------------------------- 6 next arm
out += ["## 6. The card's committed next arm (Rule Zero), by the outcome of each arm", ""]
for arm in ("CTRL", "SOUP"):
    a = R["arms"][arm]
    out.append(f"* **{NAME[arm]} {a['outcome']}**: {NEXT[a['outcome']]}")
    if a["outcome"] == "MOVED":
        for s in ("s0", "s1"):
            out.append(f"  * {s}: rows still separated-worse against P10 (X - P10): {', '.join(a['per_seed'][s]['A']['separated_worse_rows']) or 'none'}.")
out += ["", "Adoption into any K-1 / WM-1 claim needs its own confirm on a fresh read, as H-V8F-SMOOTH-1 states. The Master Mind registers the claim row; this package does not.", ""]
out += ["## 7. Limits (stated in the amendment before the data)", "",
        "* The interval answers *another draw of episodes*; it is blind to training variance (one training run per seed) and the Y' reference removes the thread-count and session difference between X and its reference, not any of these.",
        "* The tolerances come from one replicate pair (Y', Y'').",
        "* The amendment moved the reference of the controls and the Y side after the 1-thread tables were seen; the 1-thread tables stay in `RESULTS.md` as read.", ""]
open(f"{PK}/RESULTS_A1.md", "w", encoding="utf-8", newline="\n").write("\n".join(out))
print("wrote", f"{PK}/RESULTS_A1.md")
